module TopModule(input clk, input load, input [8:0] data, output reg [8:0] q);
always @(posedge clk) begin
 if (load) q <= data;
 else q <= q >>> 1;
end
endmodule

module TopModule(input clk, input load, input [8:0] data, output [8:0] q);
reg [8:0] state;
always @(posedge clk) begin
 if (load) state <= data;
 else state <= state >>> 1;
end
assign q = state;
endmodule

module TopModule(input clk, input load, input [8:0] data, output reg signed [8:0] q);
