module TopModule(input clk, input load, input [8:0] data, output reg [8:0] q);
reg old_sign;
always @(posedge clk) begin
 if (load) q = data;
 else begin
 old_sign = q[8];
 q = q >>> 1;
 q = q + ({{8{1'b0}}, old_sign} << 8);
end
end
endmodule

module TopModule(input clk, input load, input [8:0] data, output reg [8:0] q);
reg old_sign;
always @(posedge clk) begin
 if (load) q = data;
 else begin
 old_sign = q[8];
 q = q >>> 1;
 q = q ^ ({{8{1'b0}}, old_sign} << 8);
end
end
endmodule

